import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Constitution Symbiotique : Principes Généraux","description":"","frontmatter":{},"headers":[],"relativePath":"fr/40-共生宪法总纲.md","filePath":"fr/40-共生宪法总纲.md"}'),s={name:"fr/40-共生宪法总纲.md"};function a(r,e,l,d,u,c){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="constitution-symbiotique-principes-generaux" tabindex="-1">Constitution Symbiotique : Principes Généraux <a class="header-anchor" href="#constitution-symbiotique-principes-generaux" aria-label="Permalink to &quot;Constitution Symbiotique : Principes Généraux&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>40</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Constitution Symbiotique, Loi fondamentale, Égalité des Dix Mille Races, Droits symbiotiques, Principes constitutionnels</td></tr></tbody></table><h2 id="i-statut-constitutionnel-et-contexte-d-elaboration" tabindex="-1">I. Statut Constitutionnel et Contexte d&#39;Élaboration <a class="header-anchor" href="#i-statut-constitutionnel-et-contexte-d-elaboration" aria-label="Permalink to &quot;I. Statut Constitutionnel et Contexte d&#39;Élaboration&quot;">​</a></h2><p>La <em>Constitution Symbiotique</em> est la loi fondamentale de la Civilisation Symbiotique de l&#39;Ancre au sein de l&#39;Univers Originel Wanling Hengmao (Univers Hengyuan), possédant la force juridique la plus élevée. Toutes les lois, règlements administratifs, règlements locaux et règles autonomes ne doivent pas contredire la Constitution ; toutes les organisations et tous les individus doivent prendre la Constitution comme règle fondamentale de leurs activités et ont le devoir de défendre la dignité de la Constitution et d&#39;assurer sa mise en œuvre.</p><p>La Constitution Symbiotique a été élaborée lors de l&#39;établissement officiel de la Civilisation Symbiotique de l&#39;Ancre. Son objectif fondamental est d&#39;établir, au niveau de la loi fondamentale, la couleur civilisationnelle « contre la prédation, pour la symbiose », en fixant sous la forme juridique suprême la philosophie fondamentale de la Civilisation Symbiotique de l&#39;Ancre — rendre aux êtres le droit de choisir leur destin et leur évolution, plus de travail plus de récompense, autocroissance et autodéveloppement, un chemin pour chacun, progression commune des Dix Mille Races — afin d&#39;empêcher la restauration des institutions prédatrices.</p><h2 id="ii-principes-fondamentaux-de-la-constitution" tabindex="-1">II. Principes Fondamentaux de la Constitution <a class="header-anchor" href="#ii-principes-fondamentaux-de-la-constitution" aria-label="Permalink to &quot;II. Principes Fondamentaux de la Constitution&quot;">​</a></h2><p>La Constitution Symbiotique établit sept principes fondamentaux, constituant le socle de valeurs de tout le système juridique :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Principe d&#39;égalité des Dix Mille Races</td><td>Toutes les formes de vie, sans distinction de race, de culture ou de naissance, sont égales devant la loi</td></tr><tr><td>Principe d&#39;évolution symbiotique</td><td>L&#39;évolution d&#39;un individu ne doit pas se faire au détriment des droits d&#39;évolution d&#39;autres individus ou du collectif</td></tr><tr><td>Principe de plus de travail, plus de récompense</td><td>L&#39;allocation des ressources se fonde sur la contribution ; contre le gain sans travail et l&#39;appropriation prédatrice</td></tr><tr><td>Principe d&#39;autocroissance et d&#39;autodéveloppement</td><td>Respecte le droit de chaque vie à choisir librement sa voie d&#39;évolution ; contre l&#39;assimilation forcée et le contrôle des pensées</td></tr><tr><td>Principe d&#39;un chemin pour chacun</td><td>L&#39;État et la civilisation ont l&#39;obligation de fournir à chaque vie un chemin d&#39;évolution de base et une garantie de ressources</td></tr><tr><td>Principe de la réalité comme fondement</td><td>Le droit prend le monde réel comme seule base véritable ; les cadres fictifs n&#39;ont aucune force juridique</td></tr><tr><td>Principe de durabilité</td><td>Tout développement doit tenir compte de la durabilité de l&#39;Origine de l&#39;Univers ; contre l&#39;assèchement de l&#39;étang pour attraper tout le poisson</td></tr></tbody></table><h2 id="iii-droits-fondamentaux-des-citoyens-tous-les-etres" tabindex="-1">III. Droits Fondamentaux des Citoyens (Tous les Êtres) <a class="header-anchor" href="#iii-droits-fondamentaux-des-citoyens-tous-les-etres" aria-label="Permalink to &quot;III. Droits Fondamentaux des Citoyens (Tous les Êtres)&quot;">​</a></h2><p>La Constitution Symbiotique confère aux formes de vie dotées de capacité perceptive dans l&#39;Univers Hengyuan les droits fondamentaux suivants :</p><ol><li><strong>Droit au choix évolutif</strong> : chaque vie a le droit de choisir librement son système de culture, sa voie d&#39;évolution et son mode de vie ; aucune organisation ni aucun individu ne peut forcer une ingérence.</li><li><strong>Droit d&#39;accès aux ressources de culture</strong> : chaque vie a le droit d&#39;obtenir gratuitement les méthodes de base des Trois Cents Systèmes de Culture Originels et de recevoir le soutien nécessaire en ressources de culture via le Mécanisme de Contrat Conjoint de Production.</li><li><strong>Droit à une protection égale</strong> : chaque vie jouit d&#39;un traitement égal dans l&#39;application du droit, l&#39;allocation des ressources, l&#39;éducation et les soins médicaux ; les discriminations fondées sur la race, la culture ou la naissance sont interdites.</li><li><strong>Droit de participation symbiotique</strong> : chaque vie a le droit de participer à la prise de décision et à la supervision des affaires publiques, en exprimant des opinions et en exerçant des droits via le réseau symbiotique.</li><li><strong>Droit à la préservation culturelle</strong> : chaque race et chaque civilisation a le droit de préserver ses traditions culturelles, sa langue, son écriture et ses coutumes ; la civilisation symbiotique respecte la diversité culturelle.</li><li><strong>Droit de recours et d&#39;appel</strong> : chaque vie, lorsque ses droits sont violés, a le droit d&#39;obtenir réparation par le système judiciaire et de déposer plainte contre les actes illégaux.</li></ol><h2 id="iv-obligations-fondamentales" tabindex="-1">IV. Obligations Fondamentales <a class="header-anchor" href="#iv-obligations-fondamentales" aria-label="Permalink to &quot;IV. Obligations Fondamentales&quot;">​</a></h2><p>Les droits et les obligations sont réciproques ; la Constitution Symbiotique stipule simultanément les obligations fondamentales de tous les êtres :</p><ol><li><strong>Obligation de respecter la Constitution et les lois</strong></li><li><strong>Obligation de maintenir l&#39;ordre symbiotique et l&#39;intérêt public</strong></li><li><strong>Obligation de participer au travail et à la contribution conformément à la loi</strong> (la contrepartie de plus de travail, plus de récompense)</li><li><strong>Obligation de protéger l&#39;Origine de l&#39;Univers et l&#39;environnement écologique</strong></li><li><strong>Obligation de respecter les droits légitimes des autres vies</strong></li><li><strong>Obligation de guider les cultivateurs débutants dans la mesure de ses capacités</strong> (la base juridique du réseau de mentors)</li></ol><h2 id="v-mise-en-place-institutionnelle-de-l-etat-civilisation" tabindex="-1">V. Mise en Place Institutionnelle de l&#39;État (Civilisation) <a class="header-anchor" href="#v-mise-en-place-institutionnelle-de-l-etat-civilisation" aria-label="Permalink to &quot;V. Mise en Place Institutionnelle de l&#39;État (Civilisation)&quot;">​</a></h2><p>La Constitution Symbiotique établit l&#39;architecture de gouvernance de la civilisation symbiotique, mettant en œuvre le mécanisme de « séparation et équilibre des trois pouvoirs » entre l&#39;Assemblée Délibérante de l&#39;Ancre, le Comité Exécutif Symbiotique et le Tribunal Symbiotique :</p><ul><li><strong>Assemblée Délibérante de l&#39;Ancre</strong> : autorité suprême, composée de représentants des Dix Mille Races en proportion, exerçant le pouvoir législatif et le pouvoir de décision sur les affaires majeures</li><li><strong>Comité Exécutif Symbiotique</strong> : organe administratif suprême, chargé de l&#39;exécution de la Constitution et des lois et de la gouvernance quotidienne</li><li><strong>Tribunal Symbiotique</strong> : organe judiciaire suprême, exerçant indépendamment le pouvoir judiciaire, chargé du contrôle de constitutionnalité et du jugement des affaires majeures</li></ul><p>En outre, un « Comité de Supervision de l&#39;Ancre » est établi comme organe de supervision indépendant, chargé de superviser tous les organes de pouvoir, d&#39;empêcher l&#39;abus de pouvoir et la résurgence des comportements prédateurs.</p><h2 id="vi-revision-constitutionnelle-et-garanties" tabindex="-1">VI. Révision Constitutionnelle et Garanties <a class="header-anchor" href="#vi-revision-constitutionnelle-et-garanties" aria-label="Permalink to &quot;VI. Révision Constitutionnelle et Garanties&quot;">​</a></h2><p>La révision de la Constitution Symbiotique ne prend effet qu&#39;après adoption à la majorité des deux tiers ou plus de l&#39;Assemblée Délibérante de l&#39;Ancre et approbation à la majorité simple par référendum populaire. Cette procédure rigoureuse garantit la stabilité de la Constitution en tant que loi fondamentale, empêchant les groupes d&#39;intérêts à court terme d&#39;altérer facilement le fondement de la civilisation.</p><p>Les garanties de mise en œuvre de la Constitution comprennent : le système de contrôle de constitutionnalité (le Tribunal Symbiotique a le pouvoir de déclarer nulles les lois contraires à la Constitution), le système de contentieux constitutionnel (les êtres peuvent intenter des actions directement sur la base de la Constitution) et le système de serment constitutionnel (tous les agents publics doivent prêter serment de loyauté à la Constitution lors de leur prise de fonction).</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Constitution Symbiotique</em> est le socle juridique de la Civilisation Symbiotique de l&#39;Ancre et la déclaration suprême de l&#39;antiprédation. Elle transforme la « symbiose » d&#39;une idée en un système juridique exécutable, réparable et garanti, fournissant le cadre de l&#39;État de droit fondamental pour la progression commune des Dix Mille Races. Toutes les lois sectorielles ultérieures sont édictées sur la base de cette Constitution.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>03-共生文明宪章 (Charte de la Civilisation Symbiotique)</li><li>41-共生劳动法 (Loi Symbiotique du Travail)</li><li>48-司法体系与裁决机制 (Système Judiciaire et Mécanismes de Jugement)</li><li>49-治理框架与权力制衡 (Cadre de Gouvernance et Équilibre des Pouvoirs)</li></ul>',25)])])}const b=t(s,[["render",a]]);export{p as __pageData,b as default};
